export default async function record({ body, analysis }, ctx) {
  const id = body?.fileId;
  if (
    !id ||
    !body?.fileName ||
    !body?.text ||
    typeof analysis?.candidateName !== "string" ||
    typeof analysis?.facts !== "string"
  )
    throw Error("Invalid resume input");
  const key = "resume-review:" + id;
  let s = await ctx.state.get(key);
  if (s) {
    if (s.fileName !== body.fileName || s.text !== body.text)
      throw Error("File changed for existing review");
    return {
      body: { fileId: id, candidateName: s.candidateName, facts: s.facts, status: s.phase },
    };
  }
  s = {
    fileId: id,
    fileName: body.fileName,
    text: body.text,
    candidateName: analysis.candidateName,
    facts: analysis.facts,
    phase: "review",
    pending: null,
  };
  await ctx.state.set(key, s);
  return { body: { fileId: id, candidateName: s.candidateName, facts: s.facts, status: "review" } };
}

