export default async function plan(
  {
    body,
    rows,
    sourceFolder,
    rejectFolder,
    kivFolder,
    shortlistFolder,
    spreadsheetId,
    notifyEmail,
    acknowledge,
    resolution,
  },
  ctx,
) {
  const id = body?.fileId,
    key = "resume-review:" + id,
    s = await ctx.state.get(key);
  if (!s || !id) throw Error("Review does not exist");
  if (
    !["REJECTED", "KIV", "SHORTLISTED"].includes(body.decision) ||
    typeof body.reason !== "string" ||
    !body.reason.trim()
  )
    throw Error("A human decision and reason are required");
  const targets = { REJECTED: rejectFolder, KIV: kivFolder, SHORTLISTED: shortlistFolder },
    target = targets[body.decision];
  if ([sourceFolder, target, spreadsheetId, notifyEmail].some((x) => !x || x.includes("YOUR_")))
    throw Error("Configure folders, workbook and internal recipient");
  if (s.phase === "review") {
    s.decision = body.decision;
    s.reason = body.reason;
    s.target = target;
    s.phase = "move";
    await ctx.state.set(key, s);
  } else if (s.decision !== body.decision || s.reason !== body.reason || s.target !== target)
    throw Error("Decision already recorded");
  if (s.pending) {
    if (acknowledge !== s.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + s.pending);
    if (resolution === "confirmed")
      s.phase = { move: "tracker", tracker: "email", email: "done" }[s.phase];
    s.pending = null;
    await ctx.state.set(key, s);
  }
  const headers = ["File ID", "Candidate Name", "Human Verdict", "Human Reason", "Review Summary"];
  if (!Array.isArray(rows) || JSON.stringify(rows[0]?.slice(0, 5)) !== JSON.stringify(headers))
    throw Error("Tracker headers must match setup");
  const matches = rows
    .slice(1)
    .map((r, i) => ({ r, i: i + 2 }))
    .filter((x) => x.r?.[0] === id);
  if (matches.length > 1) throw Error("Duplicate File ID in tracker");
  const mode = matches.length ? "update" : "append",
    range = matches.length ? `'Candidates'!A${matches[0].i}:E${matches[0].i}` : "'Candidates'!A:E",
    values = [[id, s.candidateName, s.decision, s.reason, s.facts]],
    phase = s.phase;
  if (phase !== "done") {
    s.pending = key + ":" + phase;
    await ctx.state.set(key, s);
  }
  return {
    key,
    phase,
    mode,
    range,
    values,
    fileId: id,
    target,
    sourceFolder,
    spreadsheetId,
    to: notifyEmail,
    subject: "Candidate review completed",
    message: `Candidate: ${s.candidateName}\nFile ID: ${id}\nHuman decision: ${s.decision}\nReason: ${s.reason}`,
    body: { ok: true, status: phase },
  };
}

