async function confirm(
  { key, kind, fileId, actualFileId, spreadsheetId, actualSpreadsheetId, updatedRows, messageId },
  ctx,
) {
  const s = await ctx.state.get(key);
  if (!s || s.phase !== kind || s.pending !== key + ":" + kind) throw Error("Missing reservation");
  if (kind === "move" && actualFileId !== fileId) throw Error("Unknown file move");
  if (kind === "tracker" && (actualSpreadsheetId !== spreadsheetId || updatedRows !== 1))
    throw Error("Unknown tracker write");
  if (kind === "email" && !messageId) throw Error("Unknown notification");
  s.pending = null;
  s.phase = { move: "tracker", tracker: "email", email: "done" }[kind];
  await ctx.state.set(key, s);
  return { ok: true };
}

export default async function f(input, ctx) {
  return confirm({ ...input, kind: "move" }, ctx);
}

